-- Core data model from the design doc: applications own endpoints and
-- messages; a delivery is one message going to one endpoint and is the queue
-- item; an attempt is one HTTP call for a delivery.
--
-- IDs are prefixed strings (app_, ep_, msg_, del_) generated by the service.

CREATE TABLE applications (
    id         text PRIMARY KEY,
    name       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE endpoints (
    id          text PRIMARY KEY,
    app_id      text NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    url         text NOT NULL,
    secret      text NOT NULL,
    -- Empty means the endpoint receives every event type.
    event_types text[] NOT NULL DEFAULT '{}',
    status      text NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'paused', 'disabled')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX endpoints_app_id ON endpoints (app_id);

CREATE TABLE messages (
    id              text PRIMARY KEY,
    app_id          text NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    event_type      text NOT NULL,
    payload         jsonb NOT NULL,
    idempotency_key text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    -- NULL keys never collide, so sends without a key are always accepted.
    UNIQUE (app_id, idempotency_key)
);

CREATE TABLE deliveries (
    id              text PRIMARY KEY,
    message_id      text NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
    endpoint_id     text NOT NULL REFERENCES endpoints (id) ON DELETE CASCADE,
    state           text NOT NULL DEFAULT 'pending'
                    CHECK (state IN ('pending', 'in_flight', 'succeeded', 'dead')),
    attempt_count   integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    -- Lease: an in_flight row whose lease has passed is claimable again.
    locked_until    timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (message_id, endpoint_id)
);

-- Keeps the dispatcher's claim query cheap: only due work is indexed.
CREATE INDEX deliveries_due ON deliveries (next_attempt_at) WHERE state = 'pending';
-- Lets the sweeper find expired leases without scanning finished rows.
CREATE INDEX deliveries_leased ON deliveries (locked_until) WHERE state = 'in_flight';
CREATE INDEX deliveries_endpoint_id ON deliveries (endpoint_id);

CREATE TABLE attempts (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    delivery_id   text NOT NULL REFERENCES deliveries (id) ON DELETE CASCADE,
    attempted_at  timestamptz NOT NULL DEFAULT now(),
    status_code   integer,          -- NULL when no response arrived
    latency_ms    integer NOT NULL,
    error         text,             -- network or timeout error, if any
    response_body text              -- first 4 KB of the response
);

CREATE INDEX attempts_delivery_id ON attempts (delivery_id, attempted_at);
